function check(input, actual, expected) {
  const [nums1, nums2] = input;
  if (!Array.isArray(actual) || actual.length !== nums1.length) return false;
  const got = [...actual].sort((a, b) => a - b);
  const want = [...nums1].sort((a, b) => a - b);
  if (got.some((v, i) => v !== want[i])) return false;
  const advantage = (arr) => arr.reduce((count, v, i) => count + (v > nums2[i] ? 1 : 0), 0);
  return advantage(actual) === advantage(expected);
}

