function validate([nums1, nums2]) {
  if (nums1.length < 1 || nums1.length > 100000) return 'nums1 needs 1 to 100000 values.';
  if (nums2.length !== nums1.length) return 'nums1 and nums2 must have the same length.';
  if ([...nums1, ...nums2].some(v => !Number.isInteger(v) || v < 0 || v > 1e9)) return 'Each value is an integer from 0 to 10^9.';
  return null;
}

