function advantageCount(nums1, nums2) {
  const n = nums1.length;
  const sorted = [...nums1].sort((a, b) => a - b);
  const order = nums2.map((_, i) => i).sort((a, b) => nums2[b] - nums2[a]);
  const result = new Array(n);
  let low = 0;
  let high = n - 1;

  for (const i of order) {
    if (sorted[high] > nums2[i]) {
      result[i] = sorted[high];
      high--;
    } else {
      result[i] = sorted[low];
      low++;
    }
  }
  return result;
}

