function advantageCount(nums1, nums2) {
  // Maximum bipartite matching (Kuhn): number k may take position p only where it wins.
  const n = nums1.length;
  const owner = new Array(n).fill(-1);
  const place = (k, seen) => {
    for (let p = 0; p < n; p++) {
      if (nums1[k] <= nums2[p] || seen[p]) continue;
      seen[p] = true;
      if (owner[p] === -1 || place(owner[p], seen)) { owner[p] = k; return true; }
    }
    return false;
  };
  for (let k = 0; k < n; k++) place(k, new Array(n).fill(false));
  // Numbers that win nowhere fill the positions left over.
  const matched = new Set(owner.filter(k => k !== -1));
  const spare = nums1.map((_, k) => k).filter(k => !matched.has(k));
  return owner.map(k => nums1[k === -1 ? spare.pop() : k]);
}

