function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 7);
  const style = rand();
  const top = style < 0.4 ? 10 : style < 0.7 ? 1000 : 1e9;
  const value = () => {
    const r = rand();
    if (r < 0.05) return 0;
    if (r < 0.1) return top;
    return Math.floor(rand() * (top + 1));
  };
  const nums1 = Array.from({ length: n }, value);
  const nums2 = Array.from({ length: n }, value);
  return [nums1, nums2];
}
